INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(39665,0,0,'Boss Cho\'gall not gonna be happy \'bout dis!',14,0,100,0,0,18925,0,0,'Rom\'ogg Bonecrusher - Aggro'),
(39665,1,0,'Dat\'s what you get! Noting!',14,0,100,0,0,18926,0,0,'Rom\'ogg Bonecrusher - Killing a player'),
(39665,2,0,'Stand still! Rom\'ogg crack your skulls!',14,0,100,0,0,18927,0,0,'Rom\'ogg Bonecrusher - Skullcracker'),
(39665,3,0,'Rom\'ogg sorry...',14,0,100,0,0,18928,0,0,'Rom\'ogg Bonecrusher - Death'),
(39665,4,0,'%s calls for help!',16,0,100,0,0,0,0,0,'Rom\'ogg Bonecrusher - Emote call for help'),
(39665,5,0,'%s prepares to unleash The Skullcracker on nearby enemies!',41,0,100,0,0,0,0,0,'Rom\'ogg Bonecrusher - Skullcracker emote'),
(39670,0,0,'RAZ SMASH!',14,0,100,0,0,18919,0,0,'Raz the Crazed'),
(39670,1,0,'Raz... Tired...',14,0,100,0,0,18920,0,0,'Raz the Crazed'),
(39679,0,0,'HERETICS! You will suffer for this interruption!',14,0,100,0,0,18589,0,0,'Corla, Herald of Twilight - Aggro'),
(39679,1,0,'There is only one true path of enlightenment! DEATH!',14,0,100,0,0,18590,0,0,'Corla, Herald of Twilight - Killing a player'),
(39679,2,0,'Bask in his power! Rise as an agent of the master\'s rage!',14,0,100,0,0,18592,0,0,'Corla, Herald of Twilight - Evolved Zealot'),
(39679,3,0,'For the master I\'d die a thousand times... A thousan...',14,0,100,0,0,18594,0,0,'Corla, Herald of Twilight - Death'),
(39679,4,0,'A Twilight Zealot has evolved!',41,0,100,0,0,0,0,0,'Corla, Herald of Twilight - Evolved Zealot emote'),
(39698,0,0,'Bodies to test my armaments upon!',14,0,100,0,0,18852,0,0,'Karsh Steelbender - Aggro'),
(39698,1,0,'Merely an impurity in the compound...',14,0,100,0,0,18853,0,0,'Karsh Steelbender - Killing a player'),
(39698,2,0,'Feel the burn!',14,0,100,0,0,18854,0,0,'Karsh Steelbender to Karsh Steelbender - Superheated Quicksilver Armor'),
(39698,3,0,'We number in the millions! Your efforts are wasted...',14,0,100,0,0,18855,0,0,'Karsh Steelbender - Death'),
(39698,4,0,'%s\'s armor shimmers with heat. Strike now!',41,0,100,0,0,0,0,0,'Karsh Steelbender to Karsh Steelbender - Aura Emote'),
(39705,0,0,'You come seeking answers? Then have them! Look upon your answer to living!',14,0,100,0,0,18899,0,0,'Ascendant Lord Obsidius - Aggro'),
(39705,1,0,'Your kind has no place in the master\'s world.',14,0,100,0,0,18900,0,0,'Ascendant Lord Obsidius - Killing a player'),
(39705,2,0,'Earth can be shaped, molded... You cannot! You are useless!',14,0,100,0,0,18901,0,0,'Ascendant Lord Obsidius - Switching shadows'),
(39705,3,0,'I cannot be destroyed... Only... de... layed...',14,0,100,0,0,18902,0,0,'Ascendant Lord Obsidius - Death'),
(39705,4,0,'%s prepares to trade places with one of his shadows!',41,0,100,0,0,0,0,0,'Ascendant Lord Obsidius - Switching shadows emote');
