(28737,0,0,0,0,0,0,0,0,'<Finkle\'s helm crackles with static.>$B$BWe haven\'t got much time. Raz looked injured. If we get to him in time there might be a chance that I can turn him back into a regular orc!$B$B<You feel a sharp pain in the back of your head and hear the jingling of coins.>$B$BSorry about that. I figured I\'d send through some gold - for your troubles and all that...',12340),
(28738,0,0,0,0,0,0,0,0,'<Finkle\'s helm crackles with static.>$B$BThat should put a stop to their armory - at least for now.$B$BRaz ran off across the ramp on the other side of the forge. GO GO GO!',12340),
(28740,0,0,0,0,0,0,0,0,'<Finkle\'s helm crackles with static.>$B$BPhew... That\'s one less thing I\'ll need to worry about if we ever make it out of this place.',12340),
(28741,1,1,0,0,0,0,0,0,'Poor Raz. He was the best friend a gnome ever had. At least we avenged his death and cleared out this hellish cavern!',12340);
INSERT INTO `creature_questender` (`id`, `quest`) VALUES
(49476,28737),
(49476,28738),
(49476,28740),
(49476,28741);
